import { readFile, writeFile } from 'node:fs/promises';
import { resolve } from 'node:path';

const root = process.cwd();
const manifestPath = resolve(root, 'package.json');
const outputPath = resolve(root, 'src/mcp/version.generated.ts');

const manifest = JSON.parse(await readFile(manifestPath, 'utf8'));
if (typeof manifest.version !== 'string' || manifest.version.length === 0) {
  throw new Error('package.json must contain a non-empty string version.');
}

const expected = [
  '// Generated by scripts/generate-mcp-version.mjs. Do not edit.',
  `export const MCP_SERVER_VERSION = ${JSON.stringify(manifest.version)};`,
  '',
].join('\n');

if (process.argv.includes('--check')) {
  const actual = await readFile(outputPath, 'utf8').catch(() => undefined);
  if (actual !== expected) {
    throw new Error('src/mcp/version.generated.ts is out of date; run pnpm run generate:mcp-version.');
  }
} else {
  await writeFile(outputPath, expected, 'utf8');
}
